// The tags this flow follows: DCS NodeIds (namespace urn:haltenberg:hcw:asu1:dcs, ns=2)
// plus the column name and unit for the CSV. Add a line here to add a column.
const tags = [
    { nodeId: "ns=2;s=HCW.ASU1.FIC-101.PV", name: "FIC-101.PV", unit: "kNm3/h", desc: "Air flow (MAC load)" },
    { nodeId: "ns=2;s=HCW.ASU1.FIC-501.PV", name: "FIC-501.PV", unit: "kNm3/h", desc: "GOX send-out" },
    { nodeId: "ns=2;s=HCW.ASU1.PIC-502.PV", name: "PIC-502.PV", unit: "bar(g)", desc: "GOX header pressure" },
    { nodeId: "ns=2;s=HCW.ASU1.AI-601.PV",  name: "AI-601.PV",  unit: "%O2",    desc: "GOX purity" },
    { nodeId: "ns=2;s=HCW.ASU1.AI-202.PV",  name: "AI-202.PV",  unit: "ppm",    desc: "CO2 after PPU" },
    { nodeId: "ns=2;s=HCW.ASU1.KPI-701.PV", name: "KPI-701.PV", unit: "kWh/Nm3", desc: "Specific power" },
];
flow.set("tags", tags);
// One subscription for all items ("multiple" mode of the OPC UA client node). The server then
// pushes a data-change notification whenever a value changes, sampled every 1 s.
msg.topic = "multiple";
msg.payload = tags.map(t => ({ nodeId: t.nodeId }));
msg.interval = 1000;
node.status({ fill: "blue", shape: "dot", text: tags.length + " tags" });
return msg;

// Time-weighted average per window (TWA_WINDOW_MINUTES, default 15), computed from OPC UA
// data-change notifications.
//
// A subscription only reports *changes*, so samples are not evenly spaced in time. A plain
// average of the notifications would over-weight busy periods. Instead every value is held until
// the next one arrives (sample-and-hold) and weighted by how long it was valid:
//
//     TWA = sum(value_i * duration_i) / sum(duration_i)
//
// Bad-quality periods (e.g. BadNoCommunication when the DCS loses its I/O) are left out of
// both sums; the CSV's coverage column says how much of the window had good data.
//
// Input: OPC UA values (msg.topic = NodeId, msg.payload = DataValue), or a "tick" to close
// windows on time even when nothing changes.
const WINDOW_MS = (Number(env.get("TWA_WINDOW_MINUTES")) || 15) * 60000;
const tags = flow.get("tags") || [];
const now = Date.now();
let st = context.get("st");
if (!st) {
    st = { start: Math.floor(now / WINDOW_MS) * WINDOW_MS, samples: 0, tags: {} };
}
for (const t of tags) {
    if (!st.tags[t.nodeId]) st.tags[t.nodeId] = { v: null, t: now, sum: 0, dur: 0 };
}

// Integrate one tag's held value up to time `upto` (ms).
function hold(s, upto) {
    if (upto <= s.t) return;
    if (s.v !== null) { s.sum += s.v * (upto - s.t); s.dur += upto - s.t; }
    s.t = upto;
}

// Close every window that has ended (more than one after e.g. a laptop sleep).
const out = [];
while (now >= st.start + WINDOW_MS) {
    const end = st.start + WINDOW_MS;
    const row = { start: st.start, end: end, samples: st.samples, values: {}, coverage: 100 };
    for (const t of tags) {
        const s = st.tags[t.nodeId];
        hold(s, end);
        row.values[t.name] = s.dur > 0 ? s.sum / s.dur : null;
        row.coverage = Math.min(row.coverage, s.dur / WINDOW_MS * 100);
        s.sum = 0; s.dur = 0;
    }
    out.push({ payload: row });
    st.start = end;
    st.samples = 0;
}

// A new value: integrate the old one up to the new one's source timestamp, then hold the new one.
if (msg.topic !== "tick") {
    const s = st.tags[msg.topic];
    const dv = msg.payload || {};
    if (s) {
        const sc = dv.statusCode;
        const good = !sc || (typeof sc.isGood === "function" ? sc.isGood() : (sc.value || 0) === 0);
        const v = dv.value ? Number(dv.value.value) : NaN;
        let ts = dv.sourceTimestamp ? new Date(dv.sourceTimestamp).getTime() : now;
        ts = Math.min(Math.max(ts, s.t), now);   // never integrate backwards or into the future
        hold(s, ts);
        s.v = good && Number.isFinite(v) ? v : null;
        st.samples += 1;
    }
}
context.set("st", st);
const left = Math.round((st.start + WINDOW_MS - now) / 1000);
node.status({ fill: "green", shape: "dot", text: `${st.samples} samples · window closes in ${Math.floor(left / 60)}:${String(left % 60).padStart(2, "0")}` });
return [out];

// One CSV line per window. The header is written when the file is new or empty, so the file
// stays valid across Node-RED restarts and redeploys.
const FILE = env.get("TWA_CSV_FILE") || "/data/exports/asu1_twa_15min.csv";
const tags = flow.get("tags") || [];
const r = msg.payload;
const iso = ms => new Date(ms).toISOString().replace(".000Z", "Z");
const num = v => v === null ? "" : (Math.abs(v) >= 100 ? v.toFixed(2) : v.toFixed(4));
let header = "";
try { header = fs.statSync(FILE).size > 0 ? "" : "x"; } catch (e) { header = "x"; }
if (header) {
    header = ["window_start_utc", "window_end_utc"].concat(tags.map(t => `${t.name} [${t.unit}]`), ["coverage_pct", "samples"]).join(",") + "\n";
}
msg.filename = FILE;
msg.payload = header + [iso(r.start), iso(r.end)].concat(tags.map(t => num(r.values[t.name])), [r.coverage.toFixed(1), r.samples]).join(",");
node.status({ fill: "green", shape: "dot", text: "last row " + iso(r.end) });
return msg;
